<script setup lang="ts">
import { BadgeRussianRuble, Building2, Plus, RefreshCw, Search, ShoppingBag, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const organizations = ref<any[]>([]);
const selected = ref<any>(null);
const createOpen = ref(false);
const loading = ref(false);
const search = ref('');
const status = ref('');
const notice = ref('');
const form = reactive({ name: '', legalName: '', inn: '', kpp: '', legalAddress: '', status: 'PROSPECT', discountTier: 0, creditLimit: 0 });
let searchTimer: ReturnType<typeof setTimeout>;
const headers = computed(() => ({ Authorization: `Bearer ${token.value}` }));
const statusLabels: Record<string, string> = { PROSPECT: 'Потенциальный клиент', ACTIVE: 'Активна', ON_HOLD: 'Приостановлена', ARCHIVED: 'В архиве' };
const memberLabels: Record<string, string> = { OWNER: 'Владелец', BUYER: 'Закупщик', ACCOUNTANT: 'Бухгалтер', EMPLOYEE: 'Сотрудник' };
const orderLabels: Record<string, string> = { NEW: 'Новый', CONFIRMED: 'Подтверждён', PAYMENT_WAITING: 'Ожидает оплату', PAID: 'Оплачен', ASSEMBLING: 'Собирается', SHIPPED: 'Отправлен', DELIVERED: 'Доставлен', CANCELLED: 'Отменён', REFUNDED: 'Возврат' };
const totals = computed(() => ({ active: organizations.value.filter(item => item.status === 'ACTIVE').length, people: organizations.value.reduce((sum, item) => sum + Number(item._count?.members || 0), 0), orders: organizations.value.reduce((sum, item) => sum + Number(item._count?.orders || 0), 0) }));

async function load() {
  loading.value = true;
  try { organizations.value = await $fetch<any[]>('/customer-360/organizations', { baseURL: config.public.apiBase, headers: headers.value, query: { search: search.value || undefined, status: status.value || undefined } }); }
  finally { loading.value = false; }
}
async function openOrganization(item: any) { selected.value = await $fetch(`/customer-360/organizations/${item.id}`, { baseURL: config.public.apiBase, headers: headers.value }); }
async function createOrganization() {
  await $fetch('/customer-360/organizations', { baseURL: config.public.apiBase, method: 'POST', headers: headers.value, body: { ...form, legalName: form.legalName || undefined, inn: form.inn || undefined, kpp: form.kpp || undefined, legalAddress: form.legalAddress || undefined, discountTier: Number(form.discountTier), creditLimit: Number(form.creditLimit) } });
  Object.assign(form, { name: '', legalName: '', inn: '', kpp: '', legalAddress: '', status: 'PROSPECT', discountTier: 0, creditLimit: 0 });
  createOpen.value = false; notice.value = 'Организация создана'; await load(); setTimeout(() => notice.value = '', 2200);
}
async function saveOrganization() {
  await $fetch(`/customer-360/organizations/${selected.value.id}`, { baseURL: config.public.apiBase, method: 'PATCH', headers: headers.value, body: { name: selected.value.name, legalName: selected.value.legalName || undefined, inn: selected.value.inn || undefined, kpp: selected.value.kpp || undefined, legalAddress: selected.value.legalAddress || undefined, status: selected.value.status, discountTier: Number(selected.value.discountTier), creditLimit: Number(selected.value.creditLimit) } });
  notice.value = 'Организация сохранена'; await load(); setTimeout(() => notice.value = '', 2200);
}
async function archiveOrganization(item:any){await $fetch(`/customer-360/organizations/${item.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:headers.value,body:{status:'ARCHIVED'}});notice.value='Организация перемещена в архив';await load();setTimeout(()=>notice.value='',2200)}
async function moveOrganizationToTrash(item:any){await $fetch(`/data-lifecycle/ORGANIZATION/${item.id}/trash`,{baseURL:config.public.apiBase,method:'POST',headers:headers.value,body:{reason:'Удалено из реестра B2B-организаций'}});if(selected.value?.id===item.id)selected.value=null;notice.value='Организация перемещена в корзину на 30 дней';await load();setTimeout(()=>notice.value='',2600)}
function organizationMenu(event:MouseEvent,item:any){openContextMenu(event,item.name,[{label:'Открыть карточку',icon:'open',action:()=>openOrganization(item)},...(item.inn?[{label:'Копировать ИНН',icon:'copy' as const,action:()=>copyText(item.inn,'ИНН скопирован')}]:[]),...(item.status!=='ARCHIVED'?[{label:'Переместить в архив',icon:'archive' as const,danger:true,separator:true,confirm:`Переместить «${item.name}» в архив?`,action:()=>archiveOrganization(item)}]:[]),...(user.value?.role==='ADMIN'?[{label:'Переместить в корзину',icon:'trash' as const,danger:true,separator:item.status==='ARCHIVED',confirm:`Переместить «${item.name}» в корзину? Восстановить организацию можно в настройках экосистемы в течение 30 дней.`,action:()=>moveOrganizationToTrash(item)}]:[])],statusLabels[item.status])}
watch(search, () => { clearTimeout(searchTimer); searchTimer = setTimeout(load, 300); });
watch(status, load);
onMounted(load);
</script>

<template><main class="org-page">
  <header class="page-header"><div><p>CRM / B2B</p><h1>Организации</h1><span>Юридические лица, сотрудники, условия продаж и вся история работы</span></div><div><button class="outline" @click="load"><RefreshCw :size="16" :class="{spin:loading}" /> Обновить</button><button class="primary" @click="createOpen=true"><Plus :size="16" /> Новая организация</button></div></header>
  <div class="page-body">
    <section class="kpis"><article><Building2 :size="18" /><span>Организации</span><strong>{{ organizations.length }}</strong><small>в текущей выборке</small></article><article><BadgeRussianRuble :size="18" /><span>Активные</span><strong>{{ totals.active }}</strong><small>с действующими условиями</small></article><article><Users :size="18" /><span>Представители</span><strong>{{ totals.people }}</strong><small>связанных сотрудников</small></article><article><ShoppingBag :size="18" /><span>Заказы B2B</span><strong>{{ totals.orders }}</strong><small>за всё время</small></article></section>
    <section class="panel"><div class="filters"><label><Search :size="16" /><input v-model="search" placeholder="Название, юридическое лицо или ИНН" /></label><select v-model="status"><option value="">Все статусы</option><option value="PROSPECT">Потенциальные</option><option value="ACTIVE">Активные</option><option value="ON_HOLD">Приостановленные</option><option value="ARCHIVED">Архив</option></select></div><div class="org-row head"><span>Организация</span><span>Реквизиты</span><span>Статус</span><span>Менеджер</span><span>Результаты</span></div><button v-for="item in organizations" :key="item.id" class="org-row" @click="openOrganization(item)" @contextmenu.prevent="organizationMenu($event,item)"><span class="identity"><i>{{ item.name.slice(0,1).toUpperCase() }}</i><span><strong>{{ item.name }}</strong><small>{{ item.legalName || 'Юридическое название не указано' }}</small></span></span><span class="stack"><b>{{ item.inn ? `ИНН ${item.inn}` : 'ИНН не указан' }}</b><small>{{ item.kpp ? `КПП ${item.kpp}` : 'КПП не указан' }}</small></span><span><em :class="`status-${item.status.toLowerCase()}`">{{ statusLabels[item.status] }}</em></span><span class="stack"><b>{{ [item.accountManager?.firstName,item.accountManager?.lastName].filter(Boolean).join(' ') || 'Не назначен' }}</b><small>{{ item.accountManager?.email || 'Нужен ответственный' }}</small></span><span class="stack"><b>{{ item._count.orders }} заказов</b><small>{{ item._count.members }} представителей · {{ item.discountTier }}% скидка</small></span></button><p v-if="!organizations.length" class="empty">Организаций пока нет — добавьте первого B2B-клиента</p></section>
  </div>

  <aside v-if="selected" class="backdrop" @click.self="selected=null"><div class="drawer"><header><div><p>КАРТОЧКА B2B</p><h2>{{ selected.name }}</h2><span>{{ selected.inn ? `ИНН ${selected.inn}` : 'Реквизиты заполняются' }}</span></div><button @click="selected=null"><X :size="19" /></button></header><div class="drawer-body"><section class="edit-grid"><label>Название<input v-model="selected.name" /></label><label>Юридическое название<input v-model="selected.legalName" /></label><label>ИНН<input v-model="selected.inn" /></label><label>КПП<input v-model="selected.kpp" /></label><label>Статус<select v-model="selected.status"><option value="PROSPECT">Потенциальный клиент</option><option value="ACTIVE">Активна</option><option value="ON_HOLD">Приостановлена</option><option value="ARCHIVED">В архиве</option></select></label><label>Скидка, %<input v-model.number="selected.discountTier" type="number" min="0" max="100" /></label><label>Кредитный лимит, ₽<input v-model.number="selected.creditLimit" type="number" min="0" /></label><label class="wide">Юридический адрес<input v-model="selected.legalAddress" /></label><button @click="saveOrganization">Сохранить изменения</button></section><section class="details"><h3><Users :size="16" /> Представители</h3><div v-for="member in selected.members" :key="member.id" class="detail-row"><span><strong>{{ [member.user.firstName,member.user.lastName].filter(Boolean).join(' ') || member.user.email }}</strong><small>{{ member.user.email }}</small></span><span><b>{{ memberLabels[member.role] }}</b><small>{{ member.jobTitle || (member.canSeeFinance ? 'Видит финансы' : 'Рабочий доступ') }}</small></span></div><p v-if="!selected.members?.length" class="empty-small">Представители ещё не добавлены</p></section><section class="details"><h3><ShoppingBag :size="16" /> Последние заказы</h3><div v-for="order in selected.orders" :key="order.id" class="detail-row"><span><strong>{{ order.orderNumber }}</strong><small>{{ new Date(order.createdAt).toLocaleDateString('ru-RU') }}</small></span><span><b>{{ Number(order.finalAmount).toLocaleString('ru-RU') }} ₽</b><small>{{ orderLabels[order.status] || order.status }}</small></span></div><p v-if="!selected.orders?.length" class="empty-small">Заказов пока нет</p></section></div></div></aside>
  <aside v-if="createOpen" class="backdrop" @click.self="createOpen=false"><form class="drawer create" @submit.prevent="createOrganization"><header><div><p>НОВЫЙ B2B-КЛИЕНТ</p><h2>Организация</h2><span>Реквизиты и коммерческие условия</span></div><button type="button" @click="createOpen=false"><X :size="19" /></button></header><div class="drawer-body edit-grid"><label>Название<input v-model="form.name" required /></label><label>Юридическое название<input v-model="form.legalName" /></label><label>ИНН<input v-model="form.inn" /></label><label>КПП<input v-model="form.kpp" /></label><label>Начальный статус<select v-model="form.status"><option value="PROSPECT">Потенциальный клиент</option><option value="ACTIVE">Активна</option></select></label><label>Скидка, %<input v-model.number="form.discountTier" type="number" min="0" max="100" /></label><label>Кредитный лимит, ₽<input v-model.number="form.creditLimit" type="number" min="0" /></label><label class="wide">Юридический адрес<input v-model="form.legalAddress" /></label><button type="submit">Создать организацию</button></div></form></aside>
  <div v-if="notice" class="toast">{{ notice }}</div>
</main></template>

<style scoped>
.org-page{min-height:100vh;background:var(--sb-bg);color:#202124;font-family:var(--sb-font)}.page-header{min-height:112px;padding:23px 5%;background:#fff;border-bottom:1px solid var(--sb-line);display:flex;align-items:center;justify-content:space-between}.page-header p,.drawer header p{margin:0 0 8px;color:var(--sb-coral);font-size:9px;font-weight:600;letter-spacing:.16em}.page-header h1{font-size:29px;margin:0 0 7px}.page-header span{font-size:10px;color:var(--sb-muted)}.page-header>div:last-child{display:flex;gap:8px}.page-header button{height:40px;padding:0 14px;border:1px solid var(--sb-line);display:flex;align-items:center;gap:7px;font-size:11px}.outline{background:#fff}.page-header .primary{background:#1d1e22;color:#fff;border-color:#1d1e22}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.page-body{max-width:1220px;margin:auto;padding:28px 5% 70px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:13px}.kpis article{background:#fff;border:1px solid var(--sb-line);padding:20px;display:grid;gap:8px}.kpis svg{color:var(--sb-coral)}.kpis span,.kpis small{font-size:10px;color:var(--sb-muted)}.kpis strong{font-size:27px;font-weight:500}.panel{background:#fff;border:1px solid var(--sb-line)}.filters{padding:18px 22px;display:flex;gap:8px;border-bottom:1px solid #eff0f2}.filters label{height:38px;flex:1;display:flex;align-items:center;gap:8px;border:1px solid var(--sb-line);padding:0 10px;color:var(--sb-muted)}.filters input{border:0;outline:0;width:100%;font-size:11px}.filters select{height:38px;border:1px solid var(--sb-line);background:#fff;padding:0 10px;font-size:10px}.org-row{width:100%;min-height:64px;padding:0 22px;display:grid;grid-template-columns:1.5fr .8fr .8fr 1.1fr 1fr;gap:14px;align-items:center;border:0;border-bottom:1px solid #eff0f2;background:#fff;text-align:left;font:10px var(--sb-font)}button.org-row:hover{background:#fafafa}.org-row.head{min-height:42px;color:var(--sb-muted);font-size:8px;text-transform:uppercase}.identity{display:flex;align-items:center;gap:10px}.identity>i{width:31px;height:31px;display:grid;place-items:center;background:#1d1e22;color:#fff;font-style:normal}.identity>span,.stack{display:grid;gap:4px}.org-row strong,.org-row b{font-size:10px;font-weight:600}.org-row small{font-size:8px;color:var(--sb-muted)}.org-row em{display:inline-block;padding:5px 7px;background:#f1f2f4;font-size:8px;font-style:normal}.org-row .status-active{color:#27865b;background:#eaf8f0}.org-row .status-on_hold{color:#9a672d;background:#fff4df}.empty{text-align:center;padding:35px;color:var(--sb-muted);font-size:10px}.backdrop{position:fixed;inset:0;z-index:600;background:#10111455}.drawer{position:absolute;right:0;top:0;bottom:0;width:min(630px,95vw);background:#fff;display:flex;flex-direction:column}.drawer>header{padding:25px 29px 20px;border-bottom:1px solid var(--sb-line);display:flex;justify-content:space-between}.drawer header h2{font-size:24px;margin:0 0 5px}.drawer header span{font-size:9px;color:var(--sb-muted)}.drawer header button{border:0;background:none}.drawer-body{padding:22px 29px;overflow:auto}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;padding-bottom:22px}.edit-grid label{display:grid;gap:6px;color:var(--sb-muted);font-size:9px}.edit-grid input,.edit-grid select{height:38px;border:1px solid var(--sb-line);padding:0 10px;background:#fff;font:10px var(--sb-font)}.edit-grid .wide{grid-column:1/-1}.edit-grid>button{align-self:end;height:38px;border:0;background:#1d1e22;color:#fff;font-size:10px}.details{border-top:1px solid #ececef;padding:19px 0}.details h3{display:flex;align-items:center;gap:8px;margin:0 0 10px;font-size:12px}.details h3 svg{color:var(--sb-coral)}.detail-row{min-height:49px;display:flex;align-items:center;justify-content:space-between;gap:15px;border-bottom:1px solid #eff0f2}.detail-row>span{display:grid;gap:4px;text-align:right}.detail-row>span:first-child{text-align:left}.detail-row strong,.detail-row b{font-size:9px}.detail-row small{font-size:8px;color:var(--sb-muted)}.empty-small{font-size:9px;color:var(--sb-muted)}.create .drawer-body{align-content:start}.toast{position:fixed;right:22px;bottom:22px;background:#1d1e22;color:#fff;padding:12px 16px;font-size:10px;z-index:800}@media(max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.org-row{grid-template-columns:1.5fr 1fr .8fr 1fr}.org-row>*:last-child{display:none}}@media(max-width:600px){.page-header{align-items:flex-start;flex-direction:column;gap:14px}.page-body{padding:20px}.filters{flex-wrap:wrap}.filters label{flex-basis:100%}.org-row{grid-template-columns:1.4fr 1fr}.org-row>*:nth-child(n+3){display:none}.edit-grid{grid-template-columns:1fr}.edit-grid .wide{grid-column:auto}}
</style>
